UPDATE ocuoc_bzcrr_l
   SET RULE_NM = #{rule.ruleNm}, CMPR_TYP_CD = #{rule.cmprTypCd},
       EDTR_ID = #{userId}, CHNG_DT = SYSTIMESTAMP
 WHERE RULE_ID = #{rule.ruleId}

