/* [서식간 규칙] 이력 등록 - insertHistory */
INSERT INTO ocuoc_bzcrh_h (HSTR_ID, RULE_ID, CHNG_CTNT, RGSR_ID, REG_DT)
VALUES (SQ_OCUOC_BZCRH_H_01.NEXTVAL, #{ruleId}, #{chngCtnt}, #{userId}, SYSTIMESTAMP)

mapper.select:
