mapper.insert:
/* [서식간 규칙] 버전 등록 - insertVersion */
INSERT INTO ocuoc_bzcrv_l (RULE_ID, RULE_VER, SCHEMA_VER, DEF_JSON, RGSR_ID, REG_DT)
VALUES (#{ruleId}, #{ruleVer}, #{schemaVer}, #{defJson,jdbcType=CLOB}, #{userId}, SYSTIMESTAMP)

mapper.update:
/* [서식간 규칙] 새 형식 머리글 수정 - updateDefHeader */
UPDATE ocuoc_bzcrr_l
   SET CUR_VER = #{rule.curVer}, USE_YN = #{rule.useYn}
 WHERE RULE_ID = #{rule.ruleId}

/* [서식간 규칙] 사용 여부 변경 - updateUse */
UPDATE ocuoc_bzcrr_l
   SET USE_YN = #{useYn}, EDTR_ID = #{userId}, CHNG_DT = SYSTIMESTAMP
 WHERE RULE_ID = #{ruleId}

mapper.select:
/* [서식간 규칙] 역할 설정 조회 - selectRoles */
SELECT WK_ID AS wkId, LEFRM_ID AS formId, ROLE_NM AS roleNm, ROLE_MTHD_CD AS methodCd, FILD_KEY AS fieldKey
  FROM ocuoc_ocrwr_l
 WHERE WK_ID = #{wkId}
 ORDER BY LEFRM_ID, ROLE_NM
